{"cards": [{"node_code": "N_072ea687b40a5b22", "definition": "研究铁路工务段及修配厂在养护维修工作中的组织架构、生产计划、人员调度、物资管理及绩效考核等管理理论与实务。", "boundary": "本节点聚焦于“管理”与“组织”层面，而非具体的技术操作或设备原理。边界在于区分“管理”与“技术”：具体的检测技术归入检测节点，具体的维修工艺归入病灾害处理节点，具体的机具使用归入机具节点。若内容涉及工务段内部的行政、经济或人力资源管理，归入本节点。", "includes": ["工务段生产组织、作业计划与调度指挥", "工务修配厂的生产管理与物资供应体系", "养护维修工作的劳动组织、安全管理制度及绩效考核"], "excludes": ["具体的线路检测技术或设备原理（归入线路检测及设备）", "具体的线路病害处理工艺或维修技术（归入线路养护维修与病灾害处理）", "具体的养护维修机具结构或机械化作业技术（归入铁路养护、维修机具和机械化）"], "sibling_distinctions": [{"other_code": "N_2b28cffd2483c3a4", "rule": "区分依据为内容属性：本节点侧重管理流程、组织制度与资源配置；病灾害处理节点侧重具体的技术工艺、维修方法及病害机理。"}, {"other_code": "N_483df9bb05b8806d", "rule": "区分依据为对象：本节点侧重对“人”和“事”的管理；机具节点侧重对“物”（设备、机械）的技术特性与应用。"}], "cross_boundary_rule": "若内容涉及“基于检测数据的维修决策管理”，若侧重决策流程与管理机制，主挂载本节点；若侧重检测算法或维修技术方案，主挂载相应技术节点。"}, {"node_code": "N_0bed9268dea70e9e", "definition": "研究铁路线路状态检测的方法、仪器、设备及其自动化系统，包括轨道几何尺寸、钢轨伤损、路基状态等的监测技术与数据处理。", "boundary": "本节点聚焦于“检测”环节，即获取线路状态信息的过程。边界在于区分“检测”与“维修”：检测是发现问题的过程，维修是解决问题的过程。若内容涉及检测数据的分析算法、检测车/仪的结构原理、自动化监测系统，归入本节点。若涉及根据检测结果进行的维修作业，归入病灾害处理节点。", "includes": ["轨道几何尺寸、钢轨探伤、路基沉降等检测技术与方法", "线路检测车辆、手持检测设备及自动化监测系统", "检测数据的采集、传输、处理及状态评估模型"], "excludes": ["具体的线路维修工艺、病害处理技术（归入线路养护维修与病灾害处理）", "工务段的管理制度、人员组织（归入工务段、工务修配厂工作组织与管理）", "养护维修机具的机械结构原理（归入铁路养护、维修机具和机械化）"], "sibling_distinctions": [{"other_code": "N_2b28cffd2483c3a4", "rule": "区分依据为工作阶段：本节点侧重“诊断”（发现问题、评估状态）；病灾害处理节点侧重“治疗”（修复病害、恢复状态）。"}, {"other_code": "N_483df9bb05b8806d", "rule": "区分依据为设备功能：本节点侧重“感知”设备（传感器、检测车）；机具节点侧重“执行”设备（捣固车、打磨车等维修机械）。"}], "cross_boundary_rule": "若内容涉及“检测与维修一体化装备”，若侧重检测传感器与数据处理，主挂载本节点；若侧重维修执行机构，主挂载机具节点；若侧重整体作业流程，可关联病灾害处理。"}, {"node_code": "N_2b28cffd2483c3a4", "definition": "研究铁路线路日常养护、定期维修的技术标准、作业工艺，以及路基、轨道、道岔等常见病害的预防、处理与灾害抢修技术。", "boundary": "本节点聚焦于“维修”与“病害处理”的具体技术内容。边界在于区分“技术”与“管理”：具体的捣固、打磨、换轨工艺归入本节点，而作业计划、人员安排归入管理节点。若内容涉及自然灾害（如洪水、地震）对线路的影响及应急抢修，归入本节点。若涉及大型结构性改造，归入旧线改造节点。", "includes": ["线路日常养护、综合维修、经常维修的作业工艺与技术标准", "路基、轨道、道岔等常见病害（如翻浆冒泥、钢轨磨耗）的处理技术", "线路灾害（如断轨、水害）的应急抢修技术与安全防护措施"], "excludes": ["线路检测技术、设备原理及自动化系统（归入线路检测及设备、检测自动化）", "工务段的生产组织、管理制度及人员管理（归入工务段、工务修配厂工作组织与管理）", "养护维修机具的机械结构、性能参数及机械化原理（归入铁路养护、维修机具和机械化）"], "sibling_distinctions": [{"other_code": "N_0bed9268dea70e9e", "rule": "区分依据为工作阶段：本节点侧重“修复”与“维护”（执行动作）；检测节点侧重“监测”与“评估”（获取信息）。"}, {"other_code": "N_072ea687b40a5b22", "rule": "区分依据为内容属性：本节点侧重“怎么做”（技术工艺、操作方法）；管理节点侧重“怎么管”（组织、计划、制度）。"}], "cross_boundary_rule": "若内容涉及“基于检测结果的维修策略”，若侧重维修工艺选择与实施，主挂载本节点；若侧重检测数据分析，主挂载检测节点；若侧重维修计划编制，主挂载管理节点。"}]}
